-- Student Dormitory Management System (SDMS)
-- Sample data for MySQL 8.0+
-- Run after 01-schema.sql.
-- IMPORTANT: password_hash values below are demonstration placeholders.
-- Replace them with real bcrypt hashes generated by your Go backend before
-- using these accounts for authentication.

USE student_dormitory;
SET NAMES utf8mb4;

START TRANSACTION;

-- 1. User accounts
INSERT INTO users
    (id, full_name, username, email, password_hash, role, phone)
VALUES
    (1, 'Administrator SDMS', 'admin', 'admin@example.com',
     'REPLACE_WITH_BCRYPT_HASH', 'admin', '+992900000001'),
    (2, 'Dormitory Manager', 'manager1', 'manager1@example.com',
     'REPLACE_WITH_BCRYPT_HASH', 'manager', '+992900000002'),
    (3, 'Ahmad Karimov', 'ahmad.k', 'ahmad@example.com',
     'REPLACE_WITH_BCRYPT_HASH', 'student', '+992900000003'),
    (4, 'Madina Saidova', 'madina.s', 'madina@example.com',
     'REPLACE_WITH_BCRYPT_HASH', 'student', '+992900000004'),
    (5, 'Farid Rahimov', 'farid.r', 'farid@example.com',
     'REPLACE_WITH_BCRYPT_HASH', 'student', '+992900000005'),
    (6, 'Nilufar Sharipova', 'nilufar.sh', 'nilufar@example.com',
     'REPLACE_WITH_BCRYPT_HASH', 'student', '+992900000006')
ON DUPLICATE KEY UPDATE
    full_name = VALUES(full_name),
    role = VALUES(role),
    phone = VALUES(phone);

-- 2. Student profiles
INSERT INTO students
    (id, user_id, student_number, faculty, study_group, course, birth_date)
VALUES
    (1, 3, 'ST-2026-001', 'Faculty of Information Technology', 'IT-31', 3, '2005-03-14'),
    (2, 4, 'ST-2026-002', 'Faculty of Economics', 'EC-21', 2, '2006-07-22'),
    (3, 5, 'ST-2026-003', 'Faculty of Information Technology', 'IT-41', 4, '2004-11-09'),
    (4, 6, 'ST-2026-004', 'Faculty of Law', 'LW-11', 1, '2007-01-30')
ON DUPLICATE KEY UPDATE
    faculty = VALUES(faculty),
    study_group = VALUES(study_group),
    course = VALUES(course);

-- 3. Dormitory buildings
INSERT INTO dormitories
    (id, name, address, total_floors, description)
VALUES
    (1, 'Dormitory No. 1', 'Khujand, University Campus', 5,
     'Main student dormitory building.'),
    (2, 'Dormitory No. 2', 'Khujand, Northern Campus', 4,
     'Additional student dormitory building.')
ON DUPLICATE KEY UPDATE
    address = VALUES(address),
    total_floors = VALUES(total_floors),
    description = VALUES(description);

-- 4. Rooms
INSERT INTO rooms
    (id, dormitory_id, room_number, floor, capacity, status)
VALUES
    (1, 1, '101', 1, 3, 'available'),
    (2, 1, '102', 1, 2, 'available'),
    (3, 1, '201', 2, 3, 'available'),
    (4, 2, '105', 1, 2, 'available'),
    (5, 2, '205', 2, 3, 'maintenance')
ON DUPLICATE KEY UPDATE
    floor = VALUES(floor),
    capacity = VALUES(capacity),
    status = VALUES(status);

-- 5. Applications
INSERT INTO applications
    (id, student_id, dormitory_id, submitted_at, status, comment,
     reviewed_by, reviewed_at)
VALUES
    (1, 1, 1, '2026-09-01 09:00:00', 'approved',
     'First-year housing request reviewed.', 2, '2026-09-02 10:00:00'),
    (2, 2, 1, '2026-09-03 11:30:00', 'approved',
     'Request approved.', 2, '2026-09-04 09:30:00'),
    (3, 3, 2, '2026-09-05 14:15:00', 'pending',
     'Waiting for review.', NULL, NULL),
    (4, 4, 2, '2026-09-06 08:45:00', 'rejected',
     'No available place at the time of review.', 2, '2026-09-07 12:00:00')
ON DUPLICATE KEY UPDATE
    status = VALUES(status),
    comment = VALUES(comment),
    reviewed_by = VALUES(reviewed_by),
    reviewed_at = VALUES(reviewed_at);

-- 6. Room allocations
INSERT INTO allocations
    (id, student_id, room_id, application_id, start_date, end_date, status)
VALUES
    (1, 1, 1, 1, '2026-09-10', NULL, 'active'),
    (2, 2, 2, 2, '2026-09-10', NULL, 'active')
ON DUPLICATE KEY UPDATE
    room_id = VALUES(room_id),
    start_date = VALUES(start_date),
    end_date = VALUES(end_date),
    status = VALUES(status);

-- 7. Payments
INSERT INTO payments
    (id, student_id, allocation_id, amount, payment_date,
     payment_period, status, payment_method)
VALUES
    (1, 1, 1, 350.00, '2026-09-10', '2026-09', 'paid', 'cash'),
    (2, 1, 1, 350.00, '2026-10-10', '2026-10', 'paid', 'bank_transfer'),
    (3, 2, 2, 350.00, '2026-09-10', '2026-09', 'paid', 'cash'),
    (4, 2, 2, 350.00, '2026-10-10', '2026-10', 'pending', 'bank_transfer'),
    (5, 3, NULL, 350.00, '2026-10-10', '2026-10', 'overdue', NULL)
ON DUPLICATE KEY UPDATE
    amount = VALUES(amount),
    payment_date = VALUES(payment_date),
    payment_period = VALUES(payment_period),
    status = VALUES(status),
    payment_method = VALUES(payment_method);

COMMIT;

-- Quick verification
SELECT 'users' AS table_name, COUNT(*) AS total_rows FROM users
UNION ALL SELECT 'students', COUNT(*) FROM students
UNION ALL SELECT 'dormitories', COUNT(*) FROM dormitories
UNION ALL SELECT 'rooms', COUNT(*) FROM rooms
UNION ALL SELECT 'applications', COUNT(*) FROM applications
UNION ALL SELECT 'allocations', COUNT(*) FROM allocations
UNION ALL SELECT 'payments', COUNT(*) FROM payments;
